META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–4: ಅರ್ಜುನನ ಏಳು ಪ್ರಶ್ನೆಗಳು ಮತ್ತು ಶ್ರೀಕೃಷ್ಣನ ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರಗಳು; 5–8: ಮರಣ ಸಮಯದಲ್ಲಿ ಮನುಷ್ಯ ಏನನ್ನು ಸ್ಮರಿಸುತ್ತಾನೋ ಅಲ್ಲಿಗೇ ಹೋಗುತ್ತಾನೆ, ಆದ್ದರಿಂದ ಸದಾ ಭಗವಂತನನ್ನು ಸ್ಮರಿಸು; 9–13: ಯೋಗಿ ಓಂ ಉಚ್ಚರಿಸುತ್ತಾ ದೇಹವನ್ನು ಹೇಗೆ ಬಿಡುತ್ತಾನೆ; 14–16: ಅನನ್ಯ ಭಕ್ತನಿಗೆ ಭಗವಂತ ಸುಲಭ, ಅವನಿಗೆ ಪುನರ್ಜನ್ಮವಿಲ್ಲ; 17–22: ಬ್ರಹ್ಮನ ಹಗಲು, ರಾತ್ರಿ ಮತ್ತು ಅವುಗಳಾಚೆ ಇರುವುದು; 23–28: ಎರಡು ಮಾರ್ಗಗಳು, ಬೆಳಕಿನ ಮಾರ್ಗ ಮತ್ತು ಹೊಗೆಯ ಮಾರ್ಗ.',
)
T = {
1: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಪುರುಷೋತ್ತಮ, ಆ ಬ್ರಹ್ಮ ಎಂದರೇನು? ಅಧ್ಯಾತ್ಮ ಎಂದರೇನು, ಕರ್ಮ ಎಂದರೇನು? ಅಧಿಭೂತ ಎಂದು ಯಾವುದನ್ನು ಕರೆಯುತ್ತಾರೆ, ಅಧಿದೈವ ಎಂದು ಯಾವುದನ್ನು ಕರೆಯುತ್ತಾರೆ?',
2: 'ಹೇ ಮಧುಸೂದನ, ಈ ದೇಹದಲ್ಲಿ ಅಧಿಯಜ್ಞ ಯಾರು, ಅವನು ಇಲ್ಲಿ ಹೇಗಿದ್ದಾನೆ? ಸಂಯಮಿಗಳು ಮರಣ ಸಮಯದಲ್ಲಿ ನಿಮ್ಮನ್ನು ಹೇಗೆ ತಿಳಿಯುತ್ತಾರೆ?',
3: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಪರಮ ಅಕ್ಷರವೇ (ಅವಿನಾಶಿಯೇ) ಬ್ರಹ್ಮ. ಜೀವಿಯ ಸ್ವಂತ ಸ್ವಭಾವವನ್ನು ಅಧ್ಯಾತ್ಮ ಎನ್ನುತ್ತಾರೆ. ಜೀವಿಗಳನ್ನು ಹುಟ್ಟಿಸುವ ಸೃಷ್ಟಿಕಾರ್ಯವನ್ನು ಕರ್ಮ ಎನ್ನುತ್ತಾರೆ.',
4: 'ಹೇ ದೇಹಧಾರಿಗಳಲ್ಲಿ ಶ್ರೇಷ್ಠ, ನಾಶವಾಗುವುದೆಲ್ಲವೂ ಅಧಿಭೂತ, ವಿರಾಟ್ ಪುರುಷ ಅಧಿದೈವ, ಈ ದೇಹದಲ್ಲಿ ಅಧಿಯಜ್ಞ ನಾನೇ.',
6: 'ಹೇ ಕೌಂತೇಯ, ಮನುಷ್ಯ ಕೊನೆಯ ಕ್ಷಣದಲ್ಲಿ ಯಾವ ಭಾವವನ್ನು ಸ್ಮರಿಸುತ್ತಾ ದೇಹವನ್ನು ಬಿಡುತ್ತಾನೋ, ಸದಾ ಆ ಭಾವದಲ್ಲಿ ಮುಳುಗಿದ್ದರಿಂದ ಅವನು ಅದನ್ನೇ ಸೇರುತ್ತಾನೆ.',
8: 'ಹೇ ಪಾರ್ಥ, ಅಭ್ಯಾಸದಿಂದ ಸಾಧಿಸಿದ, ಬೇರೆಲ್ಲೂ ಹೋಗದ ಮನಸ್ಸಿನಿಂದ ಆ ಪರಮ ದಿವ್ಯ ಪುರುಷನನ್ನು ನಿರಂತರವಾಗಿ ಧ್ಯಾನಿಸುವವನು ಅವನನ್ನೇ ಸೇರುತ್ತಾನೆ.',
9: 'ಆ ಪರಮ ಪುರುಷನನ್ನು ಸ್ಮರಿಸು: ಅವನು ಸರ್ವಜ್ಞ, ಸನಾತನ, ಎಲ್ಲರನ್ನೂ ಆಳುವವನು, ಸೂಕ್ಷ್ಮಕ್ಕಿಂತ ಸೂಕ್ಷ್ಮ, ಎಲ್ಲರ ಆಧಾರ, ಊಹೆಗೆ ಮೀರಿದ ರೂಪದವನು, ಸೂರ್ಯನಂತೆ ಹೊಳೆಯುವವನು, ಕತ್ತಲೆಗೆ ಅತೀತ.',
10: 'ಮರಣ ಸಮಯದಲ್ಲಿ ಅಚಲ ಮನಸ್ಸಿನಿಂದ, ಭಕ್ತಿ ಮತ್ತು ಯೋಗಬಲದಿಂದ, ಪ್ರಾಣವನ್ನು ಹುಬ್ಬುಗಳ ನಡುವೆ ಚೆನ್ನಾಗಿ ನಿಲ್ಲಿಸಿ ಅವನನ್ನು ಸ್ಮರಿಸುವವನು ಆ ಪರಮ ದಿವ್ಯ ಪುರುಷನನ್ನು ಸೇರುತ್ತಾನೆ.',
11: 'ವೇದವಿದರು ಯಾವುದನ್ನು ಅಕ್ಷರ ಎನ್ನುತ್ತಾರೋ, ಆಸಕ್ತಿಯಿಲ್ಲದ ಸಂನ್ಯಾಸಿಗಳು ಯಾವುದರಲ್ಲಿ ಪ್ರವೇಶಿಸುತ್ತಾರೋ, ಯಾವುದನ್ನು ಪಡೆಯಲು ಜನರು ಬ್ರಹ್ಮಚರ್ಯ ಪಾಲಿಸುತ್ತಾರೋ, ಆ ಪದದ ಬಗ್ಗೆ ನಿನಗೆ ಸಂಕ್ಷೇಪವಾಗಿ ಹೇಳುತ್ತೇನೆ.',
12: 'ದೇಹದ ಎಲ್ಲ ದ್ವಾರಗಳನ್ನೂ ಮುಚ್ಚಿ, ಮನಸ್ಸನ್ನು ಹೃದಯದಲ್ಲಿ ನಿಲ್ಲಿಸಿ, ಪ್ರಾಣವನ್ನು ತಲೆಗೆ ಏರಿಸಿ, ಯೋಗಧಾರಣೆಯಲ್ಲಿ ಸ್ಥಿರವಾಗಿ,',
13: '"ಓಂ" ಎಂಬ ಏಕಾಕ್ಷರ ಬ್ರಹ್ಮವನ್ನು ಉಚ್ಚರಿಸುತ್ತಾ, ನನ್ನನ್ನು ಸ್ಮರಿಸುತ್ತಾ ದೇಹವನ್ನು ಬಿಡುವವನು ಪರಮ ಗತಿಯನ್ನು ಸೇರುತ್ತಾನೆ.',
14: 'ಹೇ ಪಾರ್ಥ, ಬೇರೆ ಯಾವುದರಲ್ಲೂ ಮನಸ್ಸಿಡದೆ, ಸದಾ, ಪ್ರತಿದಿನ ನನ್ನನ್ನು ಸ್ಮರಿಸುವವನಿಗೆ, ನಿತ್ಯ ನನ್ನೊಂದಿಗೆ ಕೂಡಿರುವ ಆ ಯೋಗಿಗೆ ನಾನು ಸುಲಭ.',
15: 'ನನ್ನನ್ನು ಸೇರಿದ ಮಹಾತ್ಮರು ದುಃಖಗಳ ನೆಲೆಯಾದ, ಶಾಶ್ವತವಲ್ಲದ ಈ ಲೋಕದಲ್ಲಿ ಮತ್ತೆ ಹುಟ್ಟುವುದಿಲ್ಲ, ಏಕೆಂದರೆ ಅವರು ಪರಮ ಸಿದ್ಧಿಯನ್ನು ಪಡೆದಿದ್ದಾರೆ.',
16: 'ಹೇ ಅರ್ಜುನ, ಬ್ರಹ್ಮಲೋಕದವರೆಗಿನ ಎಲ್ಲ ಲೋಕಗಳಿಂದಲೂ ಹಿಂತಿರುಗಲೇಬೇಕು. ಆದರೆ ಹೇ ಕೌಂತೇಯ, ನನ್ನನ್ನು ಸೇರಿದವನಿಗೆ ಪುನರ್ಜನ್ಮವಿಲ್ಲ.',
17: 'ಬ್ರಹ್ಮನ ಒಂದು ಹಗಲು ಸಾವಿರ ಯುಗಗಳು, ಅವನ ರಾತ್ರಿಯೂ ಸಾವಿರ ಯುಗಗಳು ಎಂದು ತಿಳಿದವರೇ ಹಗಲು-ರಾತ್ರಿಯ ನಿಜವಾದ ಅರ್ಥವನ್ನು ತಿಳಿದವರು.',
18: 'ಬ್ರಹ್ಮನ ಹಗಲು ಬಂದಾಗ ಕಾಣುವುದೆಲ್ಲವೂ ಅವ್ಯಕ್ತದಿಂದ ಪ್ರಕಟವಾಗುತ್ತದೆ. ರಾತ್ರಿ ಬಂದಾಗ ಅದೇ ಅವ್ಯಕ್ತದಲ್ಲಿ ಲಯವಾಗುತ್ತದೆ.',
19: 'ಹೇ ಪಾರ್ಥ, ಇದೇ ಜೀವಿಗಳ ಸಮೂಹ ಮತ್ತೆ ಮತ್ತೆ ಹುಟ್ಟಿ, ರಾತ್ರಿ ಬಂದಾಗ ಅಸಹಾಯಕವಾಗಿ ಲಯವಾಗುತ್ತದೆ, ಹಗಲು ಬಂದಾಗ ಮತ್ತೆ ಪ್ರಕಟವಾಗುತ್ತದೆ.',
20: 'ಆದರೆ ಆ ಅವ್ಯಕ್ತಕ್ಕೂ ಅತೀತವಾದ ಇನ್ನೊಂದು ಸನಾತನ ಅವ್ಯಕ್ತ ಭಾವವಿದೆ. ಎಲ್ಲ ಜೀವಿಗಳು ನಾಶವಾದರೂ ಅದು ನಾಶವಾಗುವುದಿಲ್ಲ.',
21: 'ಅದನ್ನೇ ಅವ್ಯಕ್ತ, ಅಕ್ಷರ ಎನ್ನುತ್ತಾರೆ, ಅದನ್ನೇ ಪರಮ ಗತಿ ಎನ್ನುತ್ತಾರೆ. ಅದನ್ನು ಸೇರಿದವರು ಹಿಂತಿರುಗುವುದಿಲ್ಲ. ಅದೇ ನನ್ನ ಪರಮ ಧಾಮ.',
22: 'ಹೇ ಪಾರ್ಥ, ಯಾರಲ್ಲಿ ಎಲ್ಲ ಜೀವಿಗಳೂ ಇವೆಯೋ, ಯಾರಿಂದ ಈ ಎಲ್ಲವೂ ವ್ಯಾಪಿಸಿದೆಯೋ, ಆ ಪರಮ ಪುರುಷನನ್ನು ಅನನ್ಯ ಭಕ್ತಿಯಿಂದ ಮಾತ್ರ ಪಡೆಯಬಹುದು.',
23: 'ಹೇ ಭರತಶ್ರೇಷ್ಠ, ದೇಹವನ್ನು ಬಿಡುವ ಯೋಗಿಗಳು ಯಾವ ಕಾಲದಲ್ಲಿ ಹಿಂತಿರುಗುವುದಿಲ್ಲವೋ, ಯಾವ ಕಾಲದಲ್ಲಿ ಹಿಂತಿರುಗುತ್ತಾರೋ ಅದನ್ನು ಈಗ ಹೇಳುತ್ತೇನೆ.',
24: 'ಅಗ್ನಿ, ಜ್ಯೋತಿ, ಹಗಲು, ಶುಕ್ಲಪಕ್ಷ, ಉತ್ತರಾಯಣದ ಆರು ತಿಂಗಳು: ಈ ಮಾರ್ಗದಲ್ಲಿ ಹೋಗುವ ಬ್ರಹ್ಮಜ್ಞಾನಿಗಳು ಬ್ರಹ್ಮವನ್ನು ಸೇರುತ್ತಾರೆ.',
25: 'ಹೊಗೆ, ರಾತ್ರಿ, ಕೃಷ್ಣಪಕ್ಷ, ದಕ್ಷಿಣಾಯನದ ಆರು ತಿಂಗಳು: ಈ ಮಾರ್ಗದಲ್ಲಿ ಹೋಗುವ ಯೋಗಿ ಚಂದ್ರನ ಬೆಳಕನ್ನು ಸೇರಿ ಹಿಂತಿರುಗುತ್ತಾನೆ.',
26: 'ಲೋಕದ ಈ ಎರಡು ಮಾರ್ಗಗಳು, ಶುಕ್ಲ ಮತ್ತು ಕೃಷ್ಣ, ಸನಾತನವೆಂದು ಭಾವಿಸಲಾಗಿದೆ. ಒಂದರಿಂದ ಹೋಗುವವನು ಹಿಂತಿರುಗುವುದಿಲ್ಲ, ಇನ್ನೊಂದರಿಂದ ಹೋಗುವವನು ಮತ್ತೆ ಬರುತ್ತಾನೆ.',
27: 'ಹೇ ಪಾರ್ಥ, ಈ ಎರಡು ಮಾರ್ಗಗಳನ್ನು ತಿಳಿದ ಯಾವ ಯೋಗಿಯೂ ಮೋಹಗೊಳ್ಳುವುದಿಲ್ಲ. ಆದ್ದರಿಂದ ಹೇ ಅರ್ಜುನ, ಸದಾ ಯೋಗದಲ್ಲಿ ಸ್ಥಿರನಾಗಿರು.',
28: 'ಇದನ್ನು ತಿಳಿದ ಯೋಗಿ ವೇದಾಧ್ಯಯನ, ಯಜ್ಞ, ತಪಸ್ಸು ಮತ್ತು ದಾನಗಳಿಗೆ ಹೇಳಲಾದ ಪುಣ್ಯಫಲಗಳೆಲ್ಲವನ್ನೂ ಮೀರಿ, ಪರಮ ಆದಿ ಧಾಮವನ್ನು ಸೇರುತ್ತಾನೆ.',
}
